// Le cœur intégré dans "ti" — path1-9
const HEART_PATH = `m 185.5418,0.55721777 c -2.006,0.248 -3.16,2.26200003 -3.475,4.08500003 -0.405,2.376 -1.883,4.701 -1.213,7.1669992 0.49,1.466 2.396,2.38 3.746,1.45 1.784,-0.937 2.246,-3.078 2.612,-4.8849992 0.447,-1.883 1.421,-3.834 0.957,-5.821 -0.351,-1.121 -1.38,-2.12600003 -2.627,-1.99600003 z m 15.986,13.34799923 c -2.837,0.294 -5.042,2.309 -7.584,3.394 -1.402,0.724 -2.886,2.042 -2.66,3.782 0.364,1.64 2.36,2.184 3.801,1.73 2.255,-0.59 4.118,-2.078 6.242,-2.982 1.473,-0.724 3.114,-1.916 3.137,-3.725 -0.03,-1.486 -1.607,-2.289 -2.936,-2.199 z m 1.363,20.23 c -2.681,0.273 -5.524,-0.398 -8.077,0.696 -1.176,0.587 -1.985,2.256 -1.034,3.381 1.102,1.471 3.118,1.589 4.802,1.52 2.255,-0.121 4.55,0.24 6.775,-0.232 1.337,-0.291 2.843,-1.474 2.478,-2.995 -0.414,-1.712 -2.365,-2.291 -3.919,-2.353 -0.388,0 -0.628,-0.08 -1.025,-0.02 z`

// ─── Constantes SVG ───────────────────────────────────────────────────────────
const VB_W = 318.58313
const VB_H = 180.73523
const LAYER1_TRANSFORM = 'translate(-12590.13,-27499.183)'

// Le cœur est centré à environ (197, 27) dans le viewBox principal
const HEART_CX = 197
const HEART_CY = 27

// Couleurs
const BG_COLOR   = '#fc5757'
const LOGO_FILL  = '#FEFBFD'

// ─── Props ────────────────────────────────────────────────────────────────────
interface Props {
  onFinished: () => void
}

// ─── Composant principal ──────────────────────────────────────────────────────
export default function SplashAnimation({ onFinished }: Props) {
  // Largeur du clip (révèle le texte de gauche à droite)
  const clipWidth = useSharedValue(0)

  // Cœur : opacité + scale
  const heartOpacity = useSharedValue(0)
  const heartScale   = useSharedValue(0)

  // Opacité globale pour le fade-out
  const globalOpacity = useSharedValue(1)

  useEffect(() => {
    // ── 0.0 → 1.0s : révélation du texte (clipPath glisse à droite) ──────────
    clipWidth.value = withTiming(VB_W, {
      duration: 1000,
      easing: Easing.bezier(0.25, 0.1, 0.4, 1.0), // légère accélération initiale
    })

    // ── 1.05 → 1.3s : cœur spring-in ─────────────────────────────────────────
    heartOpacity.value = withDelay(1050, withTiming(1, { duration: 80 }))
    heartScale.value = withDelay(
      1050,
      withSpring(1, {
        damping: 14,     // rebond doux, pas cartoon
        stiffness: 160,
        mass: 0.7,
      })
    )

    // ── 1.3 → 1.6s : légère respiration globale ───────────────────────────────
    // (le spring du cœur donne déjà cette sensation naturellement)

    // ── 1.65 → 1.95s : fondu vers l'écran d'accueil ──────────────────────────
    globalOpacity.value = withDelay(
      1650,
      withTiming(0, {
        duration: 300,
        easing: Easing.out(Easing.quad),
      }, (finished) => {
        if (finished) runOnJS(onFinished)()
      })
    )
  }, [])

  // Props animées pour le rect du clipPath
  const clipRectProps = useAnimatedProps(() => ({
    width: clipWidth.value,
  }))

  // Props animées pour le cœur
  const heartProps = useAnimatedProps(() => {
    const s = heartScale.value
    return {
      opacity: heartOpacity.value,
      // Scale autour du centre du cœur (cx, cy)
      transform: `translate(${HEART_CX},${HEART_CY}) scale(${s}) translate(${-HEART_CX},${-HEART_CY})`,
    }
  })

  // Style animé du conteneur (fade-out)
  const containerStyle = useAnimatedStyle(() => ({
    opacity: globalOpacity.value,
  }))

  return (
    <Animated.View style={[styles.container, containerStyle]}>
      <Svg
        width="85%"
        height={undefined}
        viewBox={`0 0 ${VB_W} ${VB_H}`}
        style={{ aspectRatio: VB_W / VB_H }}
      >
        <Defs>
          {/* Le clipPath ne s'applique qu'au texte — le cœur est hors du clip */}
          <ClipPath id="petitmo-reveal">
            <AnimatedRect
              x={0}
              y={0}
              height={VB_H}
              animatedProps={clipRectProps}
            />
          </ClipPath>
        </Defs>

        {/* Texte "petitmo" révélé de gauche à droite */}
        <G clipPath="url(#petitmo-reveal)">
          <G transform={LAYER1_TRANSFORM}>
            <Path d={TEXT_PATH} fill={LOGO_FILL} />
          </G>
        </G>

        {/* Cœur — spring-in séparé, hors du clipPath */}
        <AnimatedG animatedProps={heartProps}>
          <Path d={HEART_PATH} fill={LOGO_FILL} />
        </AnimatedG>
      </Svg>
    </Animated.View>
  )
}

